$(document).ready(function(){$('.block1-2-slider').each(function(){$(this).not('.slick-initialized').slick({autoplay:$(this).data('autoplay')||false,dotsClass:'maxwidth-theme slick-dots ',arrows:false,cssEase:'linear'});if($(this).slick('getSlick').slideCount>1){$(this).slick('slickSetOption','dots',true,true)}$(this).on('beforeChange',function(event,slick,currentSlide,nextSlide){if($(this).hasClass('block-sort-1')){const nextSlideChange=$(this).find('.header-light-target-1-'+nextSlide);setWhiteHeader(nextSlideChange)}});$(this).find('.slick-dots li').each(function(){$(this).find('button').addClass('theme-bg')});if($(this).hasClass('block-sort-1')){setWhiteHeader($('.header-light-target-1-0'))}});function setWhiteHeader(nextSlide){if(!$('body').hasClass('header-is-transparent')){return}if($(nextSlide).hasClass('text-light-desktop')){$('header').addClass('header-light')}else{$('header').removeClass('header-light')}}});